-- 17A P6 item (6): vs-entries reviewer (vs_is_admin) + approved-entry SELECT so createSignedUrl works for owner/reviewer/approved media; the bucket STAYS PUBLIC. Requires P1. [APPLY]
-- 17A STORAGE PRIVACY: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/17a-storage-privacy/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL and NO Storage API operation without Joe's relayed yes + Sentinel's pass + Atlas's review of the migrations + a backup. Sentinel's inventory/backup files were NOT available to this draft (see README). Order: README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Run it a second time and it refuses at the guard (state is no longer the captured one) with nothing changed.
-- No object, no row and no data is deleted by this pack.
BEGIN;
-- repo-wide pack key (same as R1 #136 / 12A / 13A): serialises every pack run; transaction-scoped; a second run waits for a running pack to commit or roll back, for at most 5 s:
-- lock_timeout is set BEFORE the lock (so the lock wait itself is bounded) and again right after it (every later lock wait). Expiry = SQLSTATE 55P03, nothing changed.
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(2979301232487107403);
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- 1. DRIFT GUARD: live state must be EXACTLY the captured prod state (policies by name/shape/predicate, bucket settings, ACL classes, prerequisite functions). Anything else aborts with nothing applied.
DO $guard$
DECLARE
  f text[] := ARRAY[]::text[];
  v text;
BEGIN
  IF current_user <> 'postgres' THEN f := f || ('run as postgres; current_user=' || current_user); END IF;
  v := coalesce((to_regprocedure('public.vs_is_admin()') IS NOT NULL)::text, 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('req.vs_is_admin_exists: expected true but live is ' || v); END IF;
  v := coalesce((SELECT has_function_privilege('authenticated', to_regprocedure('public.vs_is_admin()'), 'EXECUTE')::text), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('req.vs_is_admin_exec_authenticated: expected true but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM unnest(ARRAY['id','status']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.vs_entries') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT');
  IF v IS DISTINCT FROM '2' THEN f := f || ('req.vs_entries_cols: expected 2 but live is ' || v); END IF;
  v := coalesce((SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = 'public.vs_entries'::regclass AND a.attname = 'id'), 'ABSENT');
  IF v IS DISTINCT FROM 'bigint' THEN f := f || ('req.vs_entries_id_bigint: expected bigint but live is ' || v); END IF;
  v := coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'vs-entries'), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('req.vs_entries_public: expected true but live is ' || v); END IF;
  v := coalesce((to_regprocedure('public.vs_entry_media_is_approved(text)') IS NOT NULL)::text, 'ABSENT');
  IF v IS DISTINCT FROM 'false' THEN f := f || ('fn.vs_entry_media_is_approved: expected false but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'vs-entries'), 'ABSENT');
  IF v IS DISTINCT FROM 'vs_media_owner_admin_read' THEN f := f || ('sel.vs-entries: expected vs_media_owner_admin_read but live is ' || v); END IF;
  IF array_length(f, 1) IS NOT NULL THEN
    RAISE EXCEPTION '17A APPLY-P6: DRIFT, ABORT, nothing applied. % mismatch(es): %', array_length(f, 1), array_to_string(f, ' ; ');
  END IF;
END
$guard$;

-- 2. INVARIANT SNAPSHOT: everything this pack must NOT change (ACL fingerprints sorted, RLS flags, every other policy, every untouched bucket row, the object name set).
CREATE TEMP TABLE _kil17a_inv ON COMMIT DROP AS
SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('vs_media_reviewer_read','vs_media_approved_read')), '(null)')::text AS val
UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('')), '(null)')::text AS val;

-- 3. THE FIX
-- vs-entries stays PUBLIC (vs-app.js still uses getPublicUrl). These policies only add the reviewer/approved read paths that createSignedUrl needs, so the bucket can be flipped private later.
CREATE OR REPLACE FUNCTION public.vs_entry_media_is_approved(p_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $f$
  SELECT CASE WHEN (string_to_array(p_name, '/'))[2] ~ '^[0-9]{1,18}$'
              THEN EXISTS (SELECT 1 FROM public.vs_entries e WHERE e.id = ((string_to_array(p_name, '/'))[2])::bigint AND e.status = 'approved')
              ELSE false END
$f$;
REVOKE ALL ON FUNCTION public.vs_entry_media_is_approved(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.vs_entry_media_is_approved(text) TO anon, authenticated, service_role;
CREATE POLICY vs_media_reviewer_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (bucket_id = 'vs-entries' AND public.vs_is_admin());
CREATE POLICY vs_media_approved_read ON storage.objects AS PERMISSIVE FOR SELECT TO anon, authenticated USING (bucket_id = 'vs-entries' AND public.vs_entry_media_is_approved(name));

-- 4. POST-CHECKS (assert; a failure rolls the whole transaction back)
DO $post$
DECLARE bad text;
BEGIN
  SELECT string_agg(name || ' (expected ' || expected || ', got ' || actual || ')', ' ; ') INTO bad FROM (
WITH a(name, actual) AS (
  SELECT 'req.vs_is_admin_exists' AS name, coalesce((to_regprocedure('public.vs_is_admin()') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_is_admin_exec_authenticated' AS name, coalesce((SELECT has_function_privilege('authenticated', to_regprocedure('public.vs_is_admin()'), 'EXECUTE')::text), 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_entries_cols' AS name, coalesce((SELECT count(*)::text FROM unnest(ARRAY['id','status']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.vs_entries') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_entries_id_bigint' AS name, coalesce((SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = 'public.vs_entries'::regclass AND a.attname = 'id'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_entries_public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'vs-entries'), 'ABSENT') AS actual
  UNION ALL SELECT 'fn.vs_entry_media_is_approved' AS name, coalesce((to_regprocedure('public.vs_entry_media_is_approved(text)') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'fn.secdef_owner_config' AS name, coalesce((SELECT p.prosecdef::text || '/' || pg_get_userbyid(p.proowner) || '/' || coalesce((SELECT string_agg(c,',') FROM unnest(p.proconfig) c),'(none)') FROM pg_proc p WHERE p.oid = to_regprocedure('public.vs_entry_media_is_approved(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'fn.exec_anon_authenticated_public' AS name, coalesce((SELECT has_function_privilege('anon', p.oid, 'EXECUTE')::text || '/' || has_function_privilege('authenticated', p.oid, 'EXECUTE')::text || '/' || coalesce((SELECT bool_or(x.grantee = 0) FROM aclexplode(p.proacl) x), false)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.vs_entry_media_is_approved(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.vs-entries' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'vs-entries'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_reviewer_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_reviewer_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_approved_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_approved_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.vs-entries.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'vs-entries'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.vs_is_admin_exists', 'true', ARRAY['true']::text[]),
  ('req.vs_is_admin_exec_authenticated', 'true', ARRAY['true']::text[]),
  ('req.vs_entries_cols', '2', ARRAY['2']::text[]),
  ('req.vs_entries_id_bigint', 'bigint', ARRAY['bigint']::text[]),
  ('req.vs_entries_public', 'true', ARRAY['true']::text[]),
  ('fn.vs_entry_media_is_approved', 'true', ARRAY['true']::text[]),
  ('fn.secdef_owner_config', 'true/postgres/search_path=""', ARRAY['true/postgres/search_path=""']::text[]),
  ('fn.exec_anon_authenticated_public', 'true/true/false', ARRAY['true/true/false']::text[]),
  ('sel.vs-entries', 'vs_media_approved_read,vs_media_owner_admin_read,vs_media_reviewer_read', ARRAY['vs_media_approved_read,vs_media_owner_admin_read,vs_media_reviewer_read']::text[]),
  ('pol.vs_media_reviewer_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.vs_media_approved_read.shape', 'SELECT|anon,authenticated|PERMISSIVE', ARRAY['SELECT|anon,authenticated|PERMISSIVE']::text[]),
  ('bucket.vs-entries.public', 'true', ARRAY['true']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT name, expected, actual, ok FROM r
  ) z WHERE NOT ok;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A APPLY-P6: POST-CHECK FAILED (transaction rolls back): %', bad; END IF;
END
$post$;
DO $invcheck$
DECLARE bad text;
BEGIN
  SELECT string_agg(a.name, ', ') INTO bad FROM _kil17a_inv a JOIN (
    SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('vs_media_reviewer_read','vs_media_approved_read')), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('')), '(null)')::text AS val
  ) b USING (name) WHERE a.val IS DISTINCT FROM b.val;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A APPLY-P6: INVARIANT CHANGED (the pack must change nothing else; transaction rolls back): %', bad; END IF;
END
$invcheck$;

-- 5. RETAINED OUTPUT: keep this result set with the change record (ok must be true on every row).
WITH a(name, actual) AS (
  SELECT 'req.vs_is_admin_exists' AS name, coalesce((to_regprocedure('public.vs_is_admin()') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_is_admin_exec_authenticated' AS name, coalesce((SELECT has_function_privilege('authenticated', to_regprocedure('public.vs_is_admin()'), 'EXECUTE')::text), 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_entries_cols' AS name, coalesce((SELECT count(*)::text FROM unnest(ARRAY['id','status']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.vs_entries') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_entries_id_bigint' AS name, coalesce((SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = 'public.vs_entries'::regclass AND a.attname = 'id'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_entries_public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'vs-entries'), 'ABSENT') AS actual
  UNION ALL SELECT 'fn.vs_entry_media_is_approved' AS name, coalesce((to_regprocedure('public.vs_entry_media_is_approved(text)') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'fn.secdef_owner_config' AS name, coalesce((SELECT p.prosecdef::text || '/' || pg_get_userbyid(p.proowner) || '/' || coalesce((SELECT string_agg(c,',') FROM unnest(p.proconfig) c),'(none)') FROM pg_proc p WHERE p.oid = to_regprocedure('public.vs_entry_media_is_approved(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'fn.exec_anon_authenticated_public' AS name, coalesce((SELECT has_function_privilege('anon', p.oid, 'EXECUTE')::text || '/' || has_function_privilege('authenticated', p.oid, 'EXECUTE')::text || '/' || coalesce((SELECT bool_or(x.grantee = 0) FROM aclexplode(p.proacl) x), false)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.vs_entry_media_is_approved(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.vs-entries' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'vs-entries'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_reviewer_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_reviewer_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_approved_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_approved_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.vs-entries.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'vs-entries'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.vs_is_admin_exists', 'true', ARRAY['true']::text[]),
  ('req.vs_is_admin_exec_authenticated', 'true', ARRAY['true']::text[]),
  ('req.vs_entries_cols', '2', ARRAY['2']::text[]),
  ('req.vs_entries_id_bigint', 'bigint', ARRAY['bigint']::text[]),
  ('req.vs_entries_public', 'true', ARRAY['true']::text[]),
  ('fn.vs_entry_media_is_approved', 'true', ARRAY['true']::text[]),
  ('fn.secdef_owner_config', 'true/postgres/search_path=""', ARRAY['true/postgres/search_path=""']::text[]),
  ('fn.exec_anon_authenticated_public', 'true/true/false', ARRAY['true/true/false']::text[]),
  ('sel.vs-entries', 'vs_media_approved_read,vs_media_owner_admin_read,vs_media_reviewer_read', ARRAY['vs_media_approved_read,vs_media_owner_admin_read,vs_media_reviewer_read']::text[]),
  ('pol.vs_media_reviewer_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.vs_media_approved_read.shape', 'SELECT|anon,authenticated|PERMISSIVE', ARRAY['SELECT|anon,authenticated|PERMISSIVE']::text[]),
  ('bucket.vs-entries.public', 'true', ARRAY['true']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'POST' AS expected, 'POST' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
ORDER BY 1;
COMMIT;
